    var statuses = custom.statuses || ['completed'];
    if (typeof statuses === 'string') statuses = statuses.split(',').map(function(s) { return s.trim(); }).filter(Boolean);
    var perStatusLimit = custom.perStatusLimit || custom.limit || 100;
